    <script>
      (function () {
        var S = document.getElementById("status"),
          DOT = document.getElementById("dot"),
          HIDBTN = document.getElementById("hid-btn");
        var state = 0,
          connected = false,
          gpIdx = null;
        function doSend() {
          try {
            fetch("/b" + state, { method: "POST", keepalive: true });
          } catch (e) {}
          if (!connected) {
            connected = true;
            DOT.classList.add("on");
            S.textContent = "CONNECTED";
          }
        }
        function send() {
          doSend();
        }
        function press(mask) {
          if (mask >= 252) {
            state = mask;
            send();
            state = 0;
            return;
          }
          if (!(state & mask)) {
            state |= mask;
            send();
          }
        }
        function release(mask) {
          if (mask >= 252) return;
          if (state & mask) {
            state &= ~mask;
            send();
          }
        }
        function btnOn(m) {
          document
            .querySelectorAll('[data-b="' + m + '"]')
            .forEach(function (e) {
              e.classList.add("active");
            });
        }
        function btnOff(m) {
          document
            .querySelectorAll('[data-b="' + m + '"]')
            .forEach(function (e) {
              e.classList.remove("active");
            });
        }
        function applyMask(m) {
          [1, 2, 4, 8, 16, 32, 64, 128].forEach(function (b) {
            if (m & b) btnOn(b);
            else btnOff(b);
          });
          state = m;
          send();
        }
        var touchMap = new Map();
        function processTouch(e) {
          e.preventDefault();
          var liveIds = new Set();
          for (var i = 0; i < e.touches.length; i++) {
            var t = e.touches[i];
            liveIds.add(t.identifier);
            var el = document.elementFromPoint(t.clientX, t.clientY);
            var m = el && el.dataset.b ? +el.dataset.b : null;
            var prev = touchMap.get(t.identifier);
            if (prev !== undefined && prev !== m) {
              touchMap.delete(t.identifier);
              release(prev);
              btnOff(prev);
            }
            if (m !== null && touchMap.get(t.identifier) !== m) {
              touchMap.set(t.identifier, m);
              press(m);
              btnOn(m);
            }
          }
          for (var p of touchMap) {
            if (!liveIds.has(p[0])) {
              touchMap.delete(p[0]);
              release(p[1]);
              btnOff(p[1]);
            }
          }
        }
        function processEnd(e) {
          e.preventDefault();
          var liveIds = new Set();
          for (var i = 0; i < e.touches.length; i++)
            liveIds.add(e.touches[i].identifier);
          for (var p of touchMap) {
            if (!liveIds.has(p[0])) {
              touchMap.delete(p[0]);
              release(p[1]);
              btnOff(p[1]);
            }
          }
        }
        document.addEventListener("touchstart", processTouch, {
          passive: false,
        });
        document.addEventListener("touchmove", processTouch, {
          passive: false,
        });
        document.addEventListener("touchend", processEnd, { passive: false });
        document.addEventListener("touchcancel", processEnd, {
          passive: false,
        });
        var mouseBtn = null;
        document.querySelectorAll("[data-b]").forEach(function (el) {
          el.addEventListener("mousedown", function (e) {
            e.preventDefault();
            var m = +el.dataset.b;
            mouseBtn = m;
            press(m);
            btnOn(m);
          });
        });
        window.addEventListener("mouseup", function () {
          if (mouseBtn !== null) {
            var m = mouseBtn;
            mouseBtn = null;
            release(m);
            btnOff(m);
          }
        });
        var KM = {
          ArrowUp: 16,
          w: 16,
          W: 16,
          ArrowDown: 32,
          s: 32,
          S: 32,
          ArrowLeft: 64,
          a: 64,
          A: 64,
          ArrowRight: 128,
          d: 128,
          D: 128,
          x: 1,
          X: 1,
          ".": 1,
          z: 2,
          Z: 2,
          ",": 2,
          Shift: 4,
          Enter: 8,
          " ": 8,
          F5: 253,
          F9: 252,
          Escape: 254,
          Tab: 255,
        };
        var kDown = new Set();
        window.addEventListener("keydown", function (e) {
          var m = KM[e.key];
          if (m !== undefined && !kDown.has(e.key)) {
            kDown.add(e.key);
            if (m >= 252) {
              state = m;
              send();
              state = 0;
            } else {
              press(m);
              btnOn(m);
            }
            e.preventDefault();
          }
        });
        window.addEventListener("keyup", function (e) {
          var m = KM[e.key];
          if (m !== undefined) {
            kDown.delete(e.key);
            if (m < 252) {
              release(m);
              btnOff(m);
            }
            e.preventDefault();
          }
        });
        var gpActive = false,
          hidConnected = false;
        window.addEventListener("gamepadconnected", function (e) {
          gpIdx = e.gamepad.index;
          S.textContent = e.gamepad.id.substring(0, 22);
          S.style.color = "#8af";
          gpActive = true;
          HIDBTN.classList.remove("show");
        });
        window.addEventListener("gamepaddisconnected", function () {
          gpIdx = null;
          gpActive = false;
          S.textContent = connected ? "CONNECTED" : "CONNECTING...";
          S.style.color = "";
          if (!hidConnected) showHidButton();
        });
        var prevGP = 0,
          gpFrames = 0;
        function pollGP() {
          try {
            var gps = navigator.getGamepads();
            if (gpIdx === null && gps) {
              for (var i = 0; i < gps.length; i++) {
                if (!gps[i] || !gps[i].connected) continue;
                for (var b = 0; b < gps[i].buttons.length; b++) {
                  if (gps[i].buttons[b].pressed) {
                    gpIdx = i;
                    gpActive = true;
                    S.textContent = gps[i].id.substring(0, 22);
                    S.style.color = "#8af";
                    HIDBTN.classList.remove("show");
                    break;
                  }
                }
                if (gpIdx !== null) break;
              }
            }
            if (gpIdx !== null && gps[gpIdx] && gps[gpIdx].connected) {
              var gp = gps[gpIdx];
              var m = 0;
              var nb = gp.buttons.length;
              if (nb > 0 && gp.buttons[0].pressed) m |= 1;
              if (nb > 2 && gp.buttons[2].pressed) m |= 2;
              if (nb > 1 && gp.buttons[1].pressed) m |= 2;
              if (nb > 8 && gp.buttons[8].pressed) m |= 4;
              if (nb > 9 && gp.buttons[9].pressed) m |= 8;
              if (nb > 12 && gp.buttons[12].pressed) m |= 16;
              if (nb > 13 && gp.buttons[13].pressed) m |= 32;
              if (nb > 14 && gp.buttons[14].pressed) m |= 64;
              if (nb > 15 && gp.buttons[15].pressed) m |= 128;
              if (gp.axes.length >= 2) {
                if (gp.axes[1] < -0.5) m |= 16;
                if (gp.axes[1] > 0.5) m |= 32;
                if (gp.axes[0] < -0.5) m |= 64;
                if (gp.axes[0] > 0.5) m |= 128;
              }
              if (gp.axes.length >= 4) {
                if (gp.axes[3] < -0.5 || gp.axes[3] > 3) m |= 16;
                if (gp.axes[3] > 0.5 && gp.axes[3] < 2) m |= 32;
                if (gp.axes[2] < -0.5) m |= 64;
                if (gp.axes[2] > 0.5) m |= 128;
              }
              if (gp.axes.length >= 8) {
                if (gp.axes[7] < -0.5) m |= 16;
                if (gp.axes[7] > 0.5) m |= 32;
                if (gp.axes[6] < -0.5) m |= 64;
                if (gp.axes[6] > 0.5) m |= 128;
              }
              if (nb > 4 && gp.buttons[4].pressed) {
                state = 254;
                send();
                state = 0;
                prevGP = m;
                requestAnimationFrame(pollGP);
                return;
              }
              if (nb > 5 && gp.buttons[5].pressed) {
                state = 255;
                send();
                state = 0;
                prevGP = m;
                requestAnimationFrame(pollGP);
                return;
              }
              if (nb > 6 && gp.buttons[6].pressed) {
                state = 253;
                send();
                state = 0;
                prevGP = m;
                requestAnimationFrame(pollGP);
                return;
              }
              if (nb > 7 && gp.buttons[7].pressed) {
                state = 252;
                send();
                state = 0;
                prevGP = m;
                requestAnimationFrame(pollGP);
                return;
              }
              gpFrames++;
              if (m !== prevGP || (m !== 0 && gpFrames % 5 === 0)) {
                applyMask(m);
                prevGP = m;
              }
            } else if (
              gpIdx !== null &&
              (!gps[gpIdx] || !gps[gpIdx].connected)
            ) {
              gpIdx = null;
              gpActive = false;
            }
          } catch (e) {}
          requestAnimationFrame(pollGP);
        }
        requestAnimationFrame(pollGP);
        var DS_VID = 0x054c,
          DS_PID = 0x0ce6,
          DS_EDGE = 0x0df2;
        var hidDevice = null,
          hidMode = null,
          hidPrevMask = -1;
        var HAT = [16, 16 | 128, 128, 32 | 128, 32, 32 | 64, 64, 16 | 64, 0];
        function parseDualSense(rid, data) {
          var m = 0,
            db,
            b0,
            b1,
            lx,
            ly;
          if (rid === 0x01 && data.byteLength >= 9 && data.byteLength <= 10) {
            lx = data.getUint8(0);
            ly = data.getUint8(1);
            db = data.getUint8(4);
            b0 = db;
            b1 = data.getUint8(5);
            var h = db & 0x0f;
            m |= HAT[h > 8 ? 8 : h];
            if (b0 & 0x20) m |= 1;
            if (b0 & 0x40) m |= 2;
            if (b0 & 0x10) m |= 2;
            if (b1 & 0x10) m |= 4;
            if (b1 & 0x20) m |= 8;
            if (b1 & 0x04) {
              state = 253;
              send();
              state = 0;
              return;
            }
            if (b1 & 0x08) {
              state = 252;
              send();
              state = 0;
              return;
            }
            if (b1 & 0x01) {
              state = 254;
              send();
              state = 0;
              return;
            }
            if (b1 & 0x02) {
              state = 255;
              send();
              state = 0;
              return;
            }
            if (lx < 64) m |= 64;
            if (lx > 192) m |= 128;
            if (ly < 64) m |= 16;
            if (ly > 192) m |= 32;
            hidMode = "bt-simple";
          } else if (rid === 0x01 && data.byteLength >= 63) {
            lx = data.getUint8(0);
            ly = data.getUint8(1);
            db = data.getUint8(7);
            b1 = data.getUint8(8);
            var h = db & 0x0f;
            m |= HAT[h > 8 ? 8 : h];
            if (db & 0x20) m |= 1;
            if (db & 0x40) m |= 2;
            if (db & 0x10) m |= 2;
            if (b1 & 0x10) m |= 4;
            if (b1 & 0x20) m |= 8;
            if (b1 & 0x04) {
              state = 253;
              send();
              state = 0;
              return;
            }
            if (b1 & 0x08) {
              state = 252;
              send();
              state = 0;
              return;
            }
            if (b1 & 0x01) {
              state = 254;
              send();
              state = 0;
              return;
            }
            if (b1 & 0x02) {
              state = 255;
              send();
              state = 0;
              return;
            }
            if (lx < 64) m |= 64;
            if (lx > 192) m |= 128;
            if (ly < 64) m |= 16;
            if (ly > 192) m |= 32;
            hidMode = "usb";
          } else if (rid === 0x31 && data.byteLength >= 77) {
            var o = 1;
            lx = data.getUint8(o);
            ly = data.getUint8(o + 1);
            db = data.getUint8(o + 7);
            b1 = data.getUint8(o + 8);
            var h = db & 0x0f;
            m |= HAT[h > 8 ? 8 : h];
            if (db & 0x20) m |= 1;
            if (db & 0x40) m |= 2;
            if (db & 0x10) m |= 2;
            if (b1 & 0x10) m |= 4;
            if (b1 & 0x20) m |= 8;
            if (b1 & 0x04) {
              state = 253;
              send();
              state = 0;
              return;
            }
            if (b1 & 0x08) {
              state = 252;
              send();
              state = 0;
              return;
            }
            if (b1 & 0x01) {
              state = 254;
              send();
              state = 0;
              return;
            }
            if (b1 & 0x02) {
              state = 255;
              send();
              state = 0;
              return;
            }
            if (lx < 64) m |= 64;
            if (lx > 192) m |= 128;
            if (ly < 64) m |= 16;
            if (ly > 192) m |= 32;
            hidMode = "bt-ext";
          } else return;
          if (m !== hidPrevMask) {
            applyMask(m);
            hidPrevMask = m;
          }
        }
        async function tryExt(dev) {
          try {
            await dev.receiveFeatureReport(0x05);
          } catch (e) {}
        }
        async function connectHID() {
          if (!navigator.hid) {
            S.textContent = "WebHID N/A";
            S.style.color = "#f44";
            return;
          }
          try {
            var devs = await navigator.hid.requestDevice({
              filters: [
                { vendorId: DS_VID, productId: DS_PID },
                { vendorId: DS_VID, productId: DS_EDGE },
              ],
            });
            if (!devs || devs.length === 0) {
              S.textContent = "NO DEVICE";
              S.style.color = "#f44";
              return;
            }
            hidDevice = devs[0];
            if (!hidDevice.opened) await hidDevice.open();
            hidConnected = true;
            DOT.classList.add("on");
            connected = true;
            HIDBTN.classList.remove("show");
            var nm = hidDevice.productName || "DualSense";
            S.textContent = "\u{1F3AE} " + nm.substring(0, 18);
            S.style.color = "#4f8";
            hidDevice.addEventListener("inputreport", function (e) {
              parseDualSense(e.reportId, e.data);
            });
            await tryExt(hidDevice);
          } catch (e) {
            if (e.name !== "NotAllowedError") {
              S.textContent = "HID ERROR";
              S.style.color = "#f44";
            }
          }
        }
        function showHidButton() {
          if (navigator.hid && !hidConnected && gpIdx === null)
            HIDBTN.classList.add("show");
        }
        HIDBTN.addEventListener("click", function (e) {
          e.preventDefault();
          e.stopPropagation();
          connectHID();
        });
        async function autoReconnect() {
          if (!navigator.hid) return;
          try {
            var devs = await navigator.hid.getDevices();
            for (var i = 0; i < devs.length; i++) {
              var d = devs[i];
              if (
                d.vendorId === DS_VID &&
                (d.productId === DS_PID || d.productId === DS_EDGE)
              ) {
                hidDevice = d;
                if (!hidDevice.opened) await hidDevice.open();
                hidConnected = true;
                DOT.classList.add("on");
                connected = true;
                HIDBTN.classList.remove("show");
                var nm = hidDevice.productName || "DualSense";
                S.textContent = "\u{1F3AE} " + nm.substring(0, 18);
                S.style.color = "#4f8";
                hidDevice.addEventListener("inputreport", function (e) {
                  parseDualSense(e.reportId, e.data);
                });
                await tryExt(hidDevice);
                return;
              }
            }
          } catch (e) {}
          setTimeout(showHidButton, 2000);
        }
        autoReconnect();
      })();
    </script>
  </body>
</html>
]=]

local html_resp = "HTTP/1.1 200 OK\r\nContent-Type:text/html\r\nConnection:close\r\n\r\n" .. html_body
